// Downloads the printable A5 poster ("affichette") of a published site.
// The PDF is generated by the backend (GET /sites/{id}/poster), owner only.

export async function downloadSitePoster(
  siteID: number,
  authenticatedFetch: (path: string, options?: RequestInit) => Promise<Response>,
) {
  const response = await authenticatedFetch(`/sites/${siteID}/poster`);

  if (!response.ok) {
    const message = (await response.text().catch(() => "")).trim();
    throw new Error(message || "Impossible de télécharger l'affichette.");
  }

  const disposition = response.headers.get("Content-Disposition") || "";
  const filename = /filename="([^"]+)"/.exec(disposition)?.[1] || "affichette.pdf";
  const url = URL.createObjectURL(await response.blob());
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}
